import java.util.*;

public class Main {
    // 低 -> 高，后写入者覆盖
    static final String[] SOURCES = {
            "default properties",
            "application.yml",
            "application-prod.yml (profile)",
            "OS env / -D system properties",
            "command line args"
    };

    static Map<String, String> merge(String profile) {
        Map<String, String> eff = new LinkedHashMap<>();
        Map<String, String> layer = new LinkedHashMap<>();
        // ① 默认属性（但用 SpringApplication 的默认值，最低优先级）
        layer.clear();
        layer.put("server.port", "8080");
        layer.put("spring.datasource.url", "jdbc:h2:mem:test");
        layer.put("logging.level.root", "INFO");
        eff.putAll(layer);

        // ② application.yml（覆盖默认）
        layer.clear();
        layer.put("server.port", "9090");
        layer.put("app.name", "demo-service");
        eff.putAll(layer);

        // ③ profile 专属（覆盖通用，未写的键自动回落）
        if (profile.equals("prod")) {
            layer.clear();
            layer.put("spring.datasource.url", "jdbc:mysql://prod-db:3306/app");
            eff.putAll(layer);
        }

        // ④ 环境变量 / -D
        layer.clear();
        layer.put("logging.level.root", "WARN");
        eff.putAll(layer);

        // ⑤ 命令行参数（最高）
        layer.clear();
        layer.put("server.port", "18080");
        eff.putAll(layer);
        return eff;
    }

    public static void main(String[] args) {
        System.out.println("=== precedence: later sources override earlier ones ===");
        for (int i = 0; i < SOURCES.length; i++)
            System.out.println("  " + (i + 1) + ". " + SOURCES[i]);

        Map<String, String> eff = merge("prod");
        System.out.println();
        System.out.println("=== effective config (profile=prod) ===");
        eff.forEach((k, v) -> System.out.printf("  %-26s = %s%n", k, v));

        System.out.println();
        System.out.println("=== where each winning value came from ===");
        System.out.println("  server.port            <- command line (highest)");
        System.out.println("  logging.level.root     <- env / -D");
        System.out.println("  spring.datasource.url  <- application-prod.yml (profile wins over application.yml)");
        System.out.println("  app.name               <- application.yml (fell back: not overridden anywhere else)");

        Map<String, String> dev = merge("dev");
        System.out.println();
        System.out.println("=== profile=dev: unset profile key falls back to application.yml ===");
        System.out.println("  spring.datasource.url  = " + dev.get("spring.datasource.url"));
        System.out.println("  server.port            = " + dev.get("server.port") + "  (command line still wins)");
        System.out.println();
        System.out.println("profile keys present in prod-only layer : 1");
        System.out.println("key count in effective map              : " + eff.size());
    }
}
